{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C60"],
      "claim": "Urapidil, the highest-transfer analogue (0.9755), had an absolute oral bioavailability of 78% in healthy volunteers; its methoxyphenyl-piperazine core is closely relevant to the query's piperazine and methoxyphenoxy motifs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Encainide, which combines a methoxyphenyl group with a saturated azacycle and amide, showed absolute oral bioavailability of 32 ± 7% in normal subjects, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Metoprolol, sharing the aryloxypropanolamine scaffold, had absolute F of 41% at 50 mg in humans, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C43"],
      "claim": "Pamatolol, another aryloxypropanolamine, showed absolute bioavailability of 64.9–103.5% in healthy male subjects, strongly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C66"],
      "claim": "Bosentan, despite a larger and more polar structure, had absolute oral bioavailability of approximately 50% in healthy volunteers, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C63"],
      "claim": "Propranolol, an aryloxypropanolamine, gave 18.9 ± 3.8% absolute F in one normal-volunteer study, providing threshold-relevant contradictory evidence; however, other propranolol studies report 25–42% F, so this is outweighed.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer human absolute-F evidence overwhelmingly supports F ≥ 20%: urapidil (72–78%), encainide (~30–42%), metoprolol (31–55%), pamatolol (65–104%), and bosentan (~50%) all exceed the threshold. The only sub-20 anchor, propranolol (18.9%), is variable and outweighed by the consistent high-F analogues sharing methoxyphenyl, piperazine, and aryloxypropanolamine features.",
  "evidence_gaps": [
    "No direct experimental F measurement for the query molecule.",
    "Propranolol low-F data and encainide wide F range introduce some uncertainty.",
    "Qualitative 'good bioavailability' records for fostemsavir and elagolix are less quantitative."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

